// Seller review (SPEC §4.1, docs/design/wireframes.md §3): the queue, one classification's detail (questions generated by
// code, the seller's statements, the audit trail), and the recorded actions — answer, accept, override, undo, publish.
// Every action goes through the pure rules in src/domain/classifier/actions.ts and questions.ts, and is recorded with
// who (seller session), when and why. Publishing creates a listing; it quotes only if a verified rate row exists.
import { and, desc, eq, inArray, isNull } from 'drizzle-orm';
import { checkValueSplit, needsValueSplit, nextStatus, undoTarget, validateOverride, type ReviewAction } from '@/domain/classifier/actions';
import { listingFromClassification, type ClassificationStatus } from '@/domain/classifier/publish';
import { applySellerAnswers, buildQuestions, type SellerQuestions } from '@/domain/classifier/questions';
import { usd } from '@/domain/money/money';
import { quoteDuty } from '@/domain/rates/engine';
import { CheckoutError } from '../checkout';
import { db } from '../db/client';
import { auditLog, classificationActions, classifications, listings, sellerStatements } from '../db/schema';
import { currentHtsIndex } from '../hts';
import { currentRateTable } from '../rates';
import { getClassificationView, type ClassificationView } from './classify';

type Row = typeof classifications.$inferSelect;

const chosenCodes = (row: Row) => [...(row.grounded?.choice?.candidates ?? [])].sort((a, b) => b.confidence - a.confidence).map((c) => c.hts10);
const questionsOf = (row: Row): SellerQuestions => buildQuestions(row.grounded?.candidates ?? [], chosenCodes(row));
const questionCount = (q: SellerQuestions) => q.choices.length + (q.exclusions.length ? 1 : 0);
const EXCL = 'exclusions';

async function loadRow(id: string): Promise<Row> {
  if (!/^[0-9a-f-]{36}$/.test(id)) throw new CheckoutError(404, 'classification not found');
  const [row] = await db.select().from(classifications).where(eq(classifications.id, id));
  if (!row || row.kind !== 'grounded') throw new CheckoutError(404, 'classification not found');
  return row;
}

/** The latest answer per question (statements are append-only). */
function latestAnswers(stmts: { questionId: string; answerId: string }[]): { answers: Record<string, string>; exclusionsApply: boolean | null } {
  const answers: Record<string, string> = {};
  let exclusionsApply: boolean | null = null;
  for (const s of stmts) {
    if (s.questionId === EXCL) exclusionsApply = s.answerId === 'exclusions:none-apply';
    else answers[s.questionId] = s.answerId;
  }
  return { answers, exclusionsApply };
}

function rateRowFor(origin: string | null, hts10: string | null) {
  if (!origin || !hts10) return undefined;
  return currentRateTable().rows.find((r) => r.origin === origin && r.hts10 === hts10);
}

// ───────────── queue ─────────────

export interface QueueRow {
  id: string;
  title: string;
  origin: string | null;
  topCode: string | null;
  hts10: string | null;
  confidence: number | null;
  reasons: string[];
  status: ClassificationStatus;
  answered: number;
  questions: number;
  updatedAt: string;
}

export async function reviewQueue(): Promise<QueueRow[]> {
  const rows = await db.select().from(classifications).where(eq(classifications.kind, 'grounded')).orderBy(desc(classifications.updatedAt)).limit(200);
  const ids = rows.map((r) => r.id);
  const stmts = ids.length ? await db.select({ classificationId: sellerStatements.classificationId, questionId: sellerStatements.questionId }).from(sellerStatements).where(inArray(sellerStatements.classificationId, ids)) : [];
  return rows.map((r) => {
    const top = [...(r.grounded?.choice?.candidates ?? [])].sort((a, b) => b.confidence - a.confidence)[0];
    const q = questionsOf(r);
    return {
      id: r.id,
      title: r.input.title,
      origin: r.input.origin,
      topCode: top?.hts10 ?? null,
      hts10: r.hts10,
      confidence: top?.confidence ?? null,
      reasons: r.reasons,
      status: r.status,
      answered: new Set(stmts.filter((s) => s.classificationId === r.id).map((s) => s.questionId)).size,
      questions: questionCount(q),
      updatedAt: r.updatedAt.toISOString(),
    };
  });
}

// ───────────── detail ─────────────

export interface ReviewDetail extends ClassificationView {
  hts10: string | null;
  priceMinor: string;
  shippingMinor: string;
  listingId: string | null;
  questions: SellerQuestions;
  answers: Record<string, string>;
  exclusionsApply: boolean | null;
  statements: { question: string; answer: string; at: string }[];
  actions: { id: string; action: string; fromStatus: string; toStatus: string; fromHts10: string | null; toHts10: string | null; reason: string | null; at: string; undone: boolean; by: string }[];
  expanded: { code: string; chain: string[] }[];
  suggested: string | null;
  publish: { code: string | null; needsSplit: boolean; verifiedRate: boolean };
  quote: { quotable: true; dutyMinor: string; deliveredMinor: string } | { quotable: false; reason: string } | null;
}

export async function reviewDetail(id: string): Promise<ReviewDetail> {
  const row = await loadRow(id);
  const view = await getClassificationView(id);
  const stmts = await db.select().from(sellerStatements).where(eq(sellerStatements.classificationId, id)).orderBy(sellerStatements.at);
  const acts = await db.select().from(classificationActions).where(eq(classificationActions.classificationId, id)).orderBy(classificationActions.at);
  const qs = questionsOf(row);
  const { answers, exclusionsApply } = latestAnswers(stmts);
  const chosen = chosenCodes(row);
  const routed = Object.keys(answers).length || exclusionsApply !== null ? applySellerAnswers(qs, answers, exclusionsApply, chosen, row.baseReasons ?? row.reasons) : null;
  const code = row.hts10 ?? chosen[0] ?? null;
  const rr = rateRowFor(row.input.origin, code);
  let quote: ReviewDetail['quote'] = null;
  if (row.status === 'PUBLISHED' && row.listingId) {
    const [l] = await db.select().from(listings).where(eq(listings.id, row.listingId));
    if (l) quote = quoteFor(l.origin, l.hts10, l.priceMinor, l.shippingMinor, l.valueSplit);
  }
  return {
    ...view,
    hts10: row.hts10,
    priceMinor: String(row.input.priceMinor),
    shippingMinor: String(row.input.shippingMinor),
    listingId: row.listingId,
    questions: qs,
    answers,
    exclusionsApply,
    statements: stmts.map((s) => ({ question: s.question, answer: s.answer, at: s.at.toISOString() })),
    actions: acts.map((a) => ({ id: String(a.id), action: a.action, fromStatus: a.fromStatus, toStatus: a.toStatus, fromHts10: a.fromHts10, toHts10: a.toHts10, reason: a.reason, at: a.at.toISOString(), undone: a.undoneAt !== null, by: a.sellerSession.slice(-4) })),
    expanded: (row.grounded?.candidates ?? []).map((c) => ({ code: c.code, chain: c.chain })),
    suggested: routed?.suggested ?? null,
    publish: { code, needsSplit: needsValueSplit(rr), verifiedRate: rr !== undefined },
    quote,
  };
}

function quoteFor(origin: string, hts10: string, priceMinor: bigint, shippingMinor: bigint, split: { case_minor: number; band_minor: number } | null): ReviewDetail['quote'] {
  const r = quoteDuty(currentRateTable(), {
    origin,
    hts10,
    entryDate: new Date().toISOString().slice(0, 10),
    customsValue: usd(priceMinor),
    quantity: 1,
    ...(split ? { valueSplit: { case: usd(BigInt(split.case_minor)), band: usd(BigInt(split.band_minor)) } } : {}),
  });
  if (r.kind !== 'OK') return { quotable: false, reason: 'No verified rate yet. Buyers will see the listing without a price until one is verified.' };
  return { quotable: true, dutyMinor: String(r.totalDuty.amountMinor), deliveredMinor: String(priceMinor + shippingMinor + r.totalDuty.amountMinor) };
}

// ───────────── actions ─────────────

async function record(tx: Pick<typeof db, 'insert'>, row: Row, action: ReviewAction | 'answers', to: { status: ClassificationStatus; hts10: string | null }, seller: string, reason: string | null) {
  const [a] = await tx
    .insert(classificationActions)
    .values({ classificationId: row.id, action, fromStatus: row.status, toStatus: to.status, fromHts10: row.hts10, toHts10: to.hts10, reason, sellerSession: seller })
    .returning({ id: classificationActions.id });
  await tx.insert(auditLog).values({ event: `classification.${action}`, entity: 'classification', entityId: row.id, sessionId: seller, data: { from: row.status, to: to.status, hts10: to.hts10, reason } });
  return String(a!.id);
}

/** Conditional update: only if the row is still in the state we read (a concurrent change → 409). */
async function moveRow(tx: Pick<typeof db, 'update'>, row: Row, set: Partial<typeof classifications.$inferInsert>) {
  const updated = await tx
    .update(classifications)
    .set({ ...set, updatedAt: new Date() })
    .where(and(eq(classifications.id, row.id), eq(classifications.status, row.status)))
    .returning({ id: classifications.id });
  if (!updated.length) throw new CheckoutError(409, 'The classification changed meanwhile. Reload and try again.');
}

export async function answerQuestions(id: string, seller: string, body: { answers: Record<string, string>; exclusionsApply: boolean | null }) {
  const row = await loadRow(id);
  if (row.status === 'PUBLISHED' || row.status === 'CLASSIFYING' || row.status === 'FAILED') throw new CheckoutError(409, `Can't answer questions on a ${row.status} classification.`);
  const qs = questionsOf(row);
  const prior = latestAnswers(await db.select({ questionId: sellerStatements.questionId, answerId: sellerStatements.answerId }).from(sellerStatements).where(eq(sellerStatements.classificationId, id)).orderBy(sellerStatements.at));
  const answers = { ...prior.answers, ...body.answers };
  const exclusionsApply = body.exclusionsApply ?? prior.exclusionsApply;
  let routed;
  try {
    routed = applySellerAnswers(qs, answers, exclusionsApply, chosenCodes(row), row.baseReasons ?? row.reasons);
  } catch (e) {
    throw new CheckoutError(400, e instanceof Error ? e.message : 'invalid answers');
  }
  // Routing reruns in code: no open reasons → the top line is settled (as an auto-accept would); a contradiction → review.
  const top = chosenCodes(row)[0] ?? null;
  const settled = !routed.needsReview && (row.status === 'PENDING_REVIEW' || row.status === 'AUTO_ACCEPTED');
  const to = settled ? { status: 'AUTO_ACCEPTED' as const, hts10: top } : routed.reasons.includes('ANSWER_CONTRADICTS') ? { status: 'PENDING_REVIEW' as const, hts10: null } : { status: row.status, hts10: row.hts10 };
  await db.transaction(async (tx) => {
    for (const [qid, oid] of Object.entries(body.answers)) {
      const q = qs.choices.find((x) => x.id === qid)!;
      const text = oid === 'none' ? 'None of these' : q.options.find((o) => o.id === oid)!.text;
      await tx.insert(sellerStatements).values({ classificationId: id, questionId: qid, question: q.text, answer: text, answerId: oid, sellerSession: seller });
    }
    if (body.exclusionsApply !== null && qs.exclusions.length) {
      await tx.insert(sellerStatements).values({
        classificationId: id,
        questionId: EXCL,
        question: `Do any of these apply? ${qs.exclusions.map((e) => e.text).join(' / ')}`,
        answer: body.exclusionsApply ? 'None of these apply to this item.' : 'One of these applies.',
        answerId: body.exclusionsApply ? 'exclusions:none-apply' : 'exclusions:one-applies',
        sellerSession: seller,
      });
    }
    await moveRow(tx, row, { reasons: routed.reasons, needsReview: routed.needsReview, status: to.status, hts10: to.hts10 });
    if (to.status !== row.status || to.hts10 !== row.hts10) await record(tx, row, 'answers', to, seller, 'seller answers');
  });
  return reviewDetail(id);
}

export async function acceptClassification(id: string, seller: string) {
  const row = await loadRow(id);
  const next = nextStatus(row.status, 'accept');
  if (!next.ok) throw new CheckoutError(409, next.error);
  const code = row.hts10 ?? chosenCodes(row)[0] ?? null;
  if (!code) throw new CheckoutError(409, 'There is no proposed code to accept; override it with a code instead.');
  const actionId = await db.transaction(async (tx) => {
    await moveRow(tx, row, { status: next.status, hts10: code, reviewedBy: seller, reviewedAt: new Date(), reviewReason: 'accepted' });
    return record(tx, row, 'accept', { status: next.status, hts10: code }, seller, null);
  });
  return { actionId, detail: await reviewDetail(id) };
}

export async function overrideClassification(id: string, seller: string, body: { hts10: string; reason: string }) {
  const row = await loadRow(id);
  const next = nextStatus(row.status, 'override');
  if (!next.ok) throw new CheckoutError(409, next.error);
  const errors = validateOverride(body, (row.grounded?.candidates ?? []).map((c) => c.code), currentHtsIndex().lookup);
  if (errors.length) throw new CheckoutError(400, errors.join(' '));
  const actionId = await db.transaction(async (tx) => {
    await moveRow(tx, row, { status: next.status, hts10: body.hts10, reviewedBy: seller, reviewedAt: new Date(), reviewReason: body.reason.trim() });
    return record(tx, row, 'override', { status: next.status, hts10: body.hts10 }, seller, body.reason.trim());
  });
  return { actionId, detail: await reviewDetail(id) };
}

export async function undoAction(id: string, seller: string, actionId: string) {
  const row = await loadRow(id);
  if (!/^\d+$/.test(actionId)) throw new CheckoutError(400, 'invalid action id');
  const [a] = await db.select().from(classificationActions).where(and(eq(classificationActions.id, BigInt(actionId)), eq(classificationActions.classificationId, id)));
  if (!a || (a.action !== 'accept' && a.action !== 'override')) throw new CheckoutError(404, 'action not found');
  const t = undoTarget({ action: a.action, fromStatus: a.fromStatus, toStatus: a.toStatus, fromHts10: a.fromHts10, toHts10: a.toHts10, undone: a.undoneAt !== null }, { status: row.status, hts10: row.hts10 });
  if (!t.ok) throw new CheckoutError(409, t.error);
  await db.transaction(async (tx) => {
    const marked = await tx.update(classificationActions).set({ undoneAt: new Date() }).where(and(eq(classificationActions.id, a.id), isNull(classificationActions.undoneAt))).returning({ id: classificationActions.id });
    if (!marked.length) throw new CheckoutError(409, 'Already undone.');
    await moveRow(tx, row, { status: t.status, hts10: t.hts10 });
    await tx.insert(auditLog).values({ event: 'classification.undo', entity: 'classification', entityId: id, sessionId: seller, data: { undid: actionId, to: t.status, hts10: t.hts10 } });
  });
  return reviewDetail(id);
}

export async function publishReviewed(id: string, seller: string, body: { valueSplit: { caseMinor: number; bandMinor: number } | null }) {
  const row = await loadRow(id);
  const next = nextStatus(row.status, 'publish');
  if (!next.ok) throw new CheckoutError(409, next.error);
  const built = listingFromClassification({ id: row.id, status: row.status, hts10: row.hts10, input: row.input });
  if (!built.ok) throw new CheckoutError(409, built.error);
  const l = built.listing;
  const needsSplit = needsValueSplit(rateRowFor(l.origin, l.hts10));
  let split: { case_minor: number; band_minor: number } | null = null;
  if (needsSplit) {
    if (!body.valueSplit) throw new CheckoutError(400, 'This line is reported by component: enter the case value and the band value.');
    const errs = checkValueSplit(body.valueSplit, row.input.priceMinor);
    if (errs.length) throw new CheckoutError(400, errs.join(' '));
    split = { case_minor: body.valueSplit.caseMinor, band_minor: body.valueSplit.bandMinor };
  }
  await db.transaction(async (tx) => {
    await tx.insert(listings).values({ ...l, currency: 'USD', valueSplit: split, facts: {} }).onConflictDoNothing({ target: listings.id });
    await moveRow(tx, row, { status: 'PUBLISHED', listingId: l.id, publishedBy: seller, publishedAt: new Date() });
    await record(tx, row, 'publish', { status: 'PUBLISHED', hts10: l.hts10 }, seller, null);
  });
  return reviewDetail(id);
}
